function a(o){let e=Math.round(Math.max(0,o.match)*100);switch(o.verdict){case`ok`:return`¡Ese era!`;case`wrongShape`:return`La mano no está como cuando la grabaste. Pon la mano igual y haz el movimiento.`;case`tooShort`:return`Lo has hecho muy rápido. Hazlo un poco más despacio.`;case`tooLong`:return`Lo has hecho muy lento. Hazlo un poco más rápido.`;case`tooLittle`:return`Has movido poco la mano. Haz el movimiento más grande.`;case`tooMuch`:return`Has movido mucho la mano. Haz el movimiento un poco más pequeño.`;case`unsure`:return`Dudo con otra letra. Haz el movimiento más claro.`;default:return`Se parece un ${e} %. Haz el movimiento como cuando lo grabaste.`}}export{a as t};